# Generated by build.py from recipe.yml for recipe http-recover-from-a-dropped-connection. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--fault', '"drop;stage=command;path=/hello.txt;times=1"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s --retry 1 --retry-all-errors -w "%{num_retries}\n" http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
